func ptrCostingControl(p unsafe.Pointer, c int32) any {
	r := (*costingcontrol.CostingControl)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (**string)(unsafe.Pointer(&r.FuelIndexID))
	case 4:
		return &r.UseLiveFuelPrice
	case 5:
		return &r.MilesPerGallon
	case 6:
		return &r.IncludeDeadheadMiles
	case 7:
		return &r.GLActualsEnabled
	case 8:
		return &r.GLRollingMonths
	case 9:
		return &r.PlannedMonthlyMiles
	case 10:
		return &r.TargetMarginPercent
	case 11:
		return &r.Version
	case 12:
		return &r.CreatedAt
	case 13:
		return &r.UpdatedAt
	}
	return nil
}

func valueCostingControl(p unsafe.Pointer, c int32) any {
	r := (*costingcontrol.CostingControl)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.FuelIndexID == nil {
			return nil
		}
		return string(*r.FuelIndexID)
	case 4:
		return r.UseLiveFuelPrice
	case 5:
		return r.MilesPerGallon
	case 6:
		return r.IncludeDeadheadMiles
	case 7:
		return r.GLActualsEnabled
	case 8:
		return r.GLRollingMonths
	case 9:
		if r.PlannedMonthlyMiles == nil {
			return nil
		}
		return *r.PlannedMonthlyMiles
	case 10:
		return r.TargetMarginPercent
	case 11:
		return r.Version
	case 12:
		return r.CreatedAt
	case 13:
		return r.UpdatedAt
	}
	return nil
}

func attachCostingControl(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*costingcontrol.CostingControl)(p)
	switch rel {
	case 0:
		r.FuelIndex = (*fuelsurcharge.FuelIndex)(child)
	case 1:
		r.Categories = append(r.Categories, (*costingcontrol.CostCategory)(child))
	}
}

func beforeCreateCostingControl(ctx context.Context, p unsafe.Pointer) error {
	return (*costingcontrol.CostingControl)(p).BeforeCreate(ctx)
}

